with flattened_attrs as (select id, plan, effective_from, currency, tier_prices, array_min(tier_prices) as lowest_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, element_at(tier_prices, 1) as entry_price, slice(tier_limits, 1, 2) as first_two_limits from price_tiers) select date_trunc('quarter', effective_from) as quarter_start, count(distinct plan) as distinct_plans, max(lowest_price) as max_lowest_price, round(avg(lowest_price), 2) as avg_lowest_price, round(avg(entry_price), 2) as avg_entry_price from flattened_attrs group by date_trunc('quarter', effective_from)
